<span class="line">  <span class="token function">render</span><span class="token punctuation">(</span>node<span class="token punctuation">,</span> datetime<span class="token punctuation">,</span> <span class="token string">&#39;zh_CN&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
