<span class="line"><span class="token function">register</span><span class="token punctuation">(</span><span class="token string">&#39;zh_CN&#39;</span><span class="token punctuation">,</span> zhLocale<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
